fn main(){let n=61usize; let steps=120; let dx=1.0; let dt=0.2; let ratio=0.08*dt/(dx*dx); let mut field=vec![0.0;n]; field[n/2]=1.0; println!("step,time,center_value,total_mass,max_value,left_boundary,right_boundary,diffusion_ratio"); for s in 0..=steps{let total:f64=field.iter().sum::<f64>()*dx; let maxv=field.iter().cloned().fold(f64::NEG_INFINITY,f64::max); println!("{},{:.6},{:.6},{:.6},{:.6},{:.6},{:.6},{:.6}",s,s as f64*dt,field[n/2],total,maxv,field[0],field[n-1],ratio); let mut updated=field.clone(); for i in 1..n-1{updated[i]=field[i]+ratio*(field[i+1]-2.0*field[i]+field[i-1]);} updated[0]=0.0; updated[n-1]=0.0; field=updated;}}
